inputs = ['jjvuid', 'fwwhu', 'gakd', 'da', 'va']
outputs = ['jjvkiyid', 'fwwhkiy', 'kwvakd', 'da', 'va']

# Let's manually trace the differences
print("Detailed analysis of changes:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"\n{i}: '{inp}' -> '{outp}'")
        # Let's see what we're adding/removing
        if len(outp) > len(inp):
            # We're adding characters
            added_chars = []
            for j in range(len(inp)):
                if j < len(outp) and inp[j] != outp[j]:
                    added_chars.append((j, inp[j], outp[j]))
            # Also check the end
            if len(outp) > len(inp):
                for j in range(len(inp), len(outp)):
                    added_chars.append((j, '_', outp[j]))

            print(f"  Added chars at positions: {added_chars}")
        else:
            print("  Same length or shorter")

# Let me look for substring patterns that could be replaced
print("\nLooking for replacement patterns...")
patterns_to_try = set()
for inp, outp in zip(inputs, outputs):
    if inp != outp:
        # Try to find common patterns that might be replaced
        for length in range(1, min(len(inp), len(outp)) + 1):
            for i in range(len(inp) - length + 1):
                pattern = inp[i:i+length]
                # See if this pattern appears in output
                if pattern in outp:
                    patterns_to_try.add(pattern)

print("Potential patterns to consider:", patterns_to_try)

